-        for (i = k_off, ii = 0; (i < dy_t) && (ii < smax_hsize); i++, ii++) {
-          sbuff[i - k_off] = (FTYPE)sl[0];
-        }
-
-        for (; (i < shgt + dy_t) && (ii < smax_hsize); i++, ii++) {
-          sbuff[i - k_off] = (FTYPE)sl[(i - dy_t)*sll];
-        }
