-          }
-
-        } else if (kh == 3) {
-
-          p2 = buff[0]; p3 = buff[1];
-          k0 = pk[0]; k1 = pk[1]; k2 = pk[2];
-
-          for (i = 0; i <= (hsize - 2); i += 2) {
