-
-            p2 = buff[i + 2]; p3 = buff[i + 3];
-
-            d0 = D2I(p0*k0 + p1*k1 + p2*k2 + buffd[i    ]);
-            d1 = D2I(p1*k0 + p2*k1 + p3*k2 + buffd[i + 1]);
-
-            dp[0  ] = FROM_S32(d0);
-            dp[dll] = FROM_S32(d1);
-
-            buffd[i    ] = 0.0;
-            buffd[i + 1] = 0.0;
-
-            dp += 2*dll;
-          }
-
-          if (i < hsize) {
-            p0 = p2; p1 = p3;
-            p2 = buff[i + 2];
-            d0 = D2I(p0*k0 + p1*k1 + p2*k2 + buffd[i]);
