-        } else if (kh == 2) {
-
-          p2 = buff[0];
-          k0 = pk[0]; k1 = pk[1];
-
-          for (i = 0; i <= (hsize - 2); i += 2) {
-            p0 = p2;
-
-            p1 = buff[i + 1]; p2 = buff[i + 2];
-
-            d0 = D2I(p0*k0 + p1*k1 + buffd[i    ]);
-            d1 = D2I(p1*k0 + p2*k1 + buffd[i + 1]);
-
-            dp[0  ] = FROM_S32(d0);
-            dp[dll] = FROM_S32(d1);
-
-            buffd[i    ] = 0.0;
-            buffd[i + 1] = 0.0;
-
-            dp += 2*dll;
-          }
-
-          if (i < hsize) {
-            p0 = p2;
-            p1 = buff[i + 1];
