-        } else /* kh == 1 */{
-
-          k0 = pk[0];
-
-          for (i = 0; i <= (hsize - 2); i += 2) {
-            p0 = buff[i]; p1 = buff[i + 1];
-
-            d0 = D2I(p0*k0 + buffd[i    ]);
