+class TestReturnValueArgument {
+
+    public static void main(String[] args) {
+        TestFramework framework = new TestFramework();
+        Scenario[] scenarios = new Scenario[2*2];
+        int scenarioIndex = 0;
+        for (int i = 0; i < 2; i++) {
+            for (int j = 0; j < 2; j++) {
