+            }
+        }
+        framework.addScenarios(scenarios);
+        framework.start();
+    }
+
+    static class IdentityObject {
+        int val;
+    }
+
+    static value class ValueHolder {
+        IdentityObject obj;
+        ValueHolder(IdentityObject obj) {
+            this.obj = obj;
+        }
+    }
