+    }
+
+    // Variant of the above test where the IdentityObject referred to by the
+    // passed and returned holder escapes within the call. The same outcome is
+    // expected.
+    @Test
+    @IR(counts = {IRNode.FAST_LOCK, "> 0", IRNode.FAST_UNLOCK, "> 0"})
